use crate::wasi::clocks::wall_clock;

struct Node;

/// Days from 1970-01-01 to 9999-12-31 inclusive of the start day.
/// Clamping keeps the year at four digits, so the date is always 10 characters.
const MAX_DAYS: u64 = 2_932_896;

/// Converts days since the Unix epoch to a (year, month, day) triple.
/// This is the civil-from-days algorithm by Howard Hinnant, for non-negative day counts.
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

fn format_date(seconds: u64) -> String {
    let mut days = seconds / 86_400;
    if days > MAX_DAYS {
        days = MAX_DAYS;
    }
    let (y, m, d) = civil_from_days(days);
    let y = if y > 9999 { 9999 } else { y };
    let s = format!("{:04}-{:02}-{:02}", y, m, d);
    if s.len() == 10 {
        s
    } else {
        String::from("1970-01-01")
    }
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let seconds = now.seconds;
        RunInfo {
            date: format_date(seconds),
            started: seconds,
        }
    }
}

export!(Node);
